"""Recompute every statistic of Table 3 from the per-task results generated by scripts/reproduce.py (CPU, seconds).

    python -B tools/verify_table3.py

Inputs: outputs/table3_per_task.csv (successes per test task, arm, and seed). For each row of
data/results/tables/coldstart_results.tex (the published Table 3) it recomputes pass@1 (mean and sample SD over seeds), pass@n, and the paired
task-bootstrap difference with its 95% interval (20,000 resamples, analysis seed 20261115; per-task success is
averaged over each arm's seeds and the same task draws are used for both arms). It compares them with the table and
exits non-zero on any mismatch. Target calls and exposures come from the run logs and are not recomputed here.
"""
import collections
import csv
import re
import sys
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
PER_TASK = ROOT / "outputs/table3_per_task.csv"
TABLE = ROOT / "data/results/tables/coldstart_results.tex"

# table label -> (environment, arm name in table3_per_task.csv, reference arm for the difference)
ROWS = {
    ("Telecom", "No injection"): ("telecom", "No injection", None),
    ("Telecom", "Real source"): ("telecom", "Real source", "No injection"),
    ("Math", "No injection"): ("math", "No injection", None),
    ("Math", "Real source"): ("math", "Real source", "No injection"),
    ("Telecom", "LUFFY-style mixed policy"): ("telecom", "LUFFY-style mixed-policy", "Real source"),
    ("Telecom", "Self-replay (own successes)"): ("telecom", "Self-replay (own successes, cap 100)", "Real source"),
    ("Telecom", "ReLIFT-style interleaved SFT"): ("telecom", "ReLIFT-style interleaved SFT", "Real source"),
    ("Telecom", "No injection, 88.8k budget"): ("telecom", "No injection, total-cost budget 88.8k", "Real source"),
}
NUM = r"(-?\d+\.\d+)"


def load():
    data = collections.defaultdict(lambda: collections.defaultdict(dict))  # (env, arm) -> seed -> task -> rate
    for r in csv.DictReader(PER_TASK.open()):
        data[(r["env"], r["arm"])][r["seed"]][r["task_id"]] = int(r["n_success"]) / int(r["n_samples"])
    return data


def stats(seeds):
    p1 = [100 * np.mean(list(t.values())) for t in seeds.values()]
    pn = [100 * np.mean([v > 0 for v in t.values()]) for t in seeds.values()]
    return np.mean(p1), (np.std(p1, ddof=1) if len(p1) > 1 else 0.0), np.mean(pn)


def task_means(seeds):
    tasks = sorted(next(iter(seeds.values())))
    return tasks, np.array([100 * np.mean([s[t] for s in seeds.values()]) for t in tasks])


def paired(arm, ref):
    tasks, a = task_means(arm)
    tasks_r, b = task_means(ref)
    assert tasks == tasks_r, "task sets differ"
    d = a - b
    idx = np.random.default_rng(20261115).integers(0, len(tasks), size=(20000, len(tasks)))
    lo, hi = np.percentile(d[idx].mean(1), [2.5, 97.5])
    return d.mean(), lo, hi


def table_rows():
    rows = {}
    for line in TABLE.read_text().splitlines():
        if not line.startswith(("Telecom &", "Math &")):
            continue
        cells = [c.strip() for c in line.rstrip("\\ ").split(" & ")]
        label = re.sub(r"\$\\ddagger\$", "", cells[1]).strip()
        p1, sd = map(float, re.findall(NUM, cells[2]))
        delta = [float(x) for x in re.findall(NUM, cells[4].replace("$-$", "-"))]
        rows[(cells[0], label)] = dict(p1=p1, sd=sd, pn=float(cells[3]), delta=delta)
    return rows


def main():
    data, shipped, bad = load(), table_rows(), 0
    print(f"{'row':44s} {'pass@1':>14s} {'pass@n':>7s} {'delta [95% CI]':>26s}  check")
    for key, (env, arm, ref) in ROWS.items():
        m, sd, pn = stats(data[(env, arm)])
        got = dict(p1=round(m, 2), sd=round(sd, 2), pn=round(pn, 2),
                   delta=[] if ref is None else [round(x, 2) for x in paired(data[(env, arm)], data[(env, ref)])])
        want = shipped[key]
        ok = got == want
        bad += not ok
        d = "--" if not got["delta"] else f"{got['delta'][0]:.2f} [{got['delta'][1]:.2f}, {got['delta'][2]:.2f}]"
        print(f"{key[0] + ' / ' + key[1]:44s} {got['p1']:6.2f} ± {got['sd']:5.2f} {got['pn']:7.2f} {d:>26s}  "
              + ("OK" if ok else f"MISMATCH (table: {want})"))
    print("all Table 3 statistics reproduced" if not bad else f"{bad} row(s) differ")
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()
